"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Two properties are load bearing:

* addresses and lengths are reported at the full width the system reports
  them at, so they can be compared with a debugger one for one, and
* a reported path is one the reader can paste into a shell or a ticket, which
  means a DOS drive letter or a UNC share, never the ``\\Device\\...`` name the
  kernel uses internally.
"""

import ctypes
import string

from . import _winapi as w
from .errors import WVasError

#: start size for the buffers handed to the path APIs; they are grown on
#: demand so that long paths are never silently truncated.
PATH_BUFFER_CHARS = 260

_MAX_PATH_BUFFER_CHARS = 1 << 16

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

#: modifier bits that sit on top of the base protection value
_PROTECTION_MODIFIERS = w.PAGE_GUARD | w.PAGE_NOCACHE | w.PAGE_WRITECOMBINE

_UNC_DEVICES = (
    "\\device\\mup",
    "\\device\\lanmanredirector",
    "\\device\\webdavredirector",
)

_max_application_address_cache = None


# ---------------------------------------------------------------------------
# pure helpers
# ---------------------------------------------------------------------------

def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: a constant goes in, a name comes out.  The guard/caching modifier
    bits are ignored so that, say, ``PAGE_READWRITE | PAGE_GUARD`` still reads
    as ``rw``.
    """
    try:
        value = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(value & ~_PROTECTION_MODIFIERS, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure: a constant goes in, a name comes out.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# process handles
# ---------------------------------------------------------------------------

def _require_platform(pid):
    if not w.AVAILABLE:
        raise WVasError(w.LOAD_ERROR, kind="unsupported", pid=pid)


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _check_pid(pid)
    _require_platform(pid)

    # Strongest rights first: GetMappedFileNameW wants VM_READ as well as
    # query rights.  Weaker rights still answer VirtualQueryEx, so fall back
    # rather than refuse the whole audit.
    attempts = (
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_LIMITED_INFORMATION | w.PROCESS_VM_READ,
        w.PROCESS_QUERY_INFORMATION,
        w.PROCESS_QUERY_LIMITED_INFORMATION,
    )
    error = w.ERROR_ACCESS_DENIED
    for access in attempts:
        ctypes.set_last_error(0)
        handle = w.OpenProcess(access, False, pid)
        if handle:
            return handle
        error = w.last_error()
        if error not in (w.ERROR_ACCESS_DENIED, w.ERROR_INVALID_PARAMETER):
            break
        if error == w.ERROR_INVALID_PARAMETER:
            # the pid does not name a live process; weaker rights will not help
            break

    raise _open_failure(pid, error)


def _open_failure(pid, error):
    if error in (w.ERROR_INVALID_PARAMETER, w.ERROR_FILE_NOT_FOUND):
        return WVasError(
            "no process with this pid", kind="no-such-process", pid=pid
        )
    if error == w.ERROR_ACCESS_DENIED:
        return WVasError(
            "the process cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    return WVasError(
        "OpenProcess failed with Win32 error %d" % (error,),
        kind="query-failed",
        pid=pid,
    )


def _max_application_address():
    """Highest address the walk has to probe, cached for the process."""
    global _max_application_address_cache
    if _max_application_address_cache is None:
        info = w.SYSTEM_INFO()
        w.GetSystemInfo(ctypes.byref(info))
        highest = int(info.lpMaximumApplicationAddress or 0) & w.POINTER_MASK
        if highest <= 0:
            highest = w.POINTER_MASK
        _max_application_address_cache = highest
    return _max_application_address_cache


# ---------------------------------------------------------------------------
# NT device paths -> paths a human can open
# ---------------------------------------------------------------------------

def _device_map():
    """Map lowercased NT device names onto their DOS drive letters."""
    mapping = {}
    buffer = ctypes.create_unicode_buffer(_MAX_PATH_BUFFER_CHARS)
    for letter in string.ascii_uppercase:
        drive = "%s:" % (letter,)
        written = w.QueryDosDeviceW(drive, buffer, _MAX_PATH_BUFFER_CHARS)
        if not written:
            continue
        # QueryDosDeviceW hands back a NUL separated list; the first entry is
        # the device the drive currently resolves to.
        target = buffer[:written].split("\x00")[0]
        if target:
            mapping[target.lower()] = drive
    return mapping


def _strip_extended_prefix(path):
    for prefix in ("\\??\\", "\\\\?\\", "\\\\.\\"):
        if path.startswith(prefix):
            return path[len(prefix):]
    return path


def _unc_from_redirector(rest):
    """Turn the tail of a network redirector device path into a UNC path.

    The redirector encodes mapped drives as ``;Z:0123456789abcdef`` in front
    of the server name; that component is not part of the share path.
    """
    parts = [part for part in rest.split("\\") if part]
    if parts and parts[0].startswith(";"):
        parts = parts[1:]
    if not parts:
        return None
    return "\\\\" + "\\".join(parts)


def _dos_path(nt_path, device_map):
    """Translate a kernel path into a path the caller can open.

    Returns ``None`` when the name cannot be turned into a drive letter or a
    UNC path, which is better than handing a ``\\Device\\...`` name to someone
    who is going to paste it into Explorer.
    """
    if not nt_path:
        return None

    path = _strip_extended_prefix(nt_path)
    if path.startswith("UNC\\"):
        return "\\\\" + path[4:]
    if len(path) >= 2 and path[1] == ":" and path[0] in string.ascii_letters:
        return path
    if path.startswith("\\\\"):
        return path
    if not path.startswith("\\"):
        return None

    lowered = path.lower()
    for device in _UNC_DEVICES:
        if lowered == device:
            return None
        if lowered.startswith(device + "\\"):
            return _unc_from_redirector(path[len(device):])

    # Longest match wins so that \Device\HarddiskVolume1 never swallows a
    # name that belongs to \Device\HarddiskVolume11.
    best = None
    for device, drive in device_map.items():
        if lowered == device:
            return drive + "\\"
        if lowered.startswith(device + "\\"):
            if best is None or len(device) > len(best[0]):
                best = (device, drive)
    if best is not None:
        return best[1] + path[len(best[0]):]
    return None


def _mapped_file_name(handle, address):
    """The kernel's name for the file mapped at ``address``, or ``None``."""
    size = PATH_BUFFER_CHARS
    while size <= _MAX_PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, size
        )
        if not written:
            # No section object is backing this address: anonymous mapping,
            # private memory or a pagefile backed section.
            return None
        if written < size - 1:
            return buffer[:written] or None
        size *= 2
    return None


def _module_file_name(handle, base):
    """``GetModuleFileNameExW`` for an image base, already a DOS path."""
    size = PATH_BUFFER_CHARS
    while size <= _MAX_PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        written = w.GetModuleFileNameExW(
            handle, ctypes.c_void_p(base), buffer, size
        )
        if not written:
            return None
        if written < size - 1:
            return buffer[:written] or None
        size *= 2
    return None


class _PathResolver:
    """Resolves the backing file of a region, once per allocation."""

    def __init__(self, handle, device_map=None):
        self._handle = handle
        self._device_map = device_map if device_map is not None else _device_map()
        self._cache = {}

    @property
    def device_map(self):
        return self._device_map

    def resolve(self, address, is_image=False):
        if address in self._cache:
            return self._cache[address]
        path = _dos_path(
            _mapped_file_name(self._handle, address), self._device_map
        )
        if path is None and is_image:
            # An image whose section name cannot be translated may still be
            # known to the loader under a perfectly ordinary path.
            path = _module_file_name(self._handle, address)
            if path is not None:
                path = _dos_path(path, self._device_map)
        self._cache[address] = path
        return path


# ---------------------------------------------------------------------------
# walking the address space
# ---------------------------------------------------------------------------

def _walk(handle, pid):
    """Yield every non-free region of the target, lowest address first.

    Each item is ``(base, size, state, type, protect, allocation_base)`` with
    the values exactly as ``VirtualQueryEx`` reported them: no masking, no
    rounding, no truncation to the width of some other architecture.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    mbi_size = ctypes.sizeof(mbi)
    highest = _max_application_address()
    address = 0
    probed = False

    while address <= highest:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), mbi_size
        )
        if not written:
            error = w.last_error()
            if not probed and error not in (
                w.ERROR_SUCCESS, w.ERROR_INVALID_PARAMETER,
            ):
                raise WVasError(
                    "VirtualQueryEx failed with Win32 error %d" % (error,),
                    kind="query-failed",
                    pid=pid,
                )
            break
        probed = True

        base = int(mbi.BaseAddress or 0) & w.POINTER_MASK
        size = int(mbi.RegionSize)
        state = int(mbi.State)

        if size <= 0:
            break
        if state != w.MEM_FREE:
            yield (
                base,
                size,
                state,
                int(mbi.Type),
                int(mbi.Protect),
                int(mbi.AllocationBase or 0) & w.POINTER_MASK,
            )

        next_address = base + size
        if next_address <= address:
            break
        address = next_address


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ordered by ``base``.  With ``include_reserved`` set, reserved
    but uncommitted ranges are reported next to the committed ones; without
    it, only committed ranges are.
    """
    handle = _open_process(pid)
    try:
        resolver = _PathResolver(handle)
        result = []
        for base, size, state, mem_type, protect, alloc_base in _walk(
            handle, pid
        ):
            if state == w.MEM_COMMIT:
                state_name = "commit"
            elif state & w.MEM_RESERVE:
                if not include_reserved:
                    continue
                state_name = "reserve"
            else:
                continue

            is_image = mem_type == w.MEM_IMAGE
            if mem_type in (w.MEM_IMAGE, w.MEM_MAPPED):
                path = resolver.resolve(alloc_base or base, is_image)
            else:
                path = None

            result.append({
                "base": base,
                "size": size,
                "state": state_name,
                "type": type_name(mem_type),
                "protect": protection_name(protect),
                "path": path,
                "image": is_image,
            })
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        w.CloseHandle(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# loaded images
# ---------------------------------------------------------------------------

def _enumerate_module_handles(handle):
    """Every module handle the loader knows about, or ``None`` on failure."""
    count = 256
    while count <= 1 << 16:
        array = (w.wt.HMODULE * count)()
        needed = w.wt.DWORD(0)
        ok = w.EnumProcessModulesEx(
            handle,
            array,
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return None
        returned = needed.value // ctypes.sizeof(w.wt.HMODULE)
        if returned <= count:
            return [int(array[i] or 0) for i in range(returned)]
        count = returned + 16
    return None


def _module_size(handle, base):
    info = w.MODULEINFO()
    ok = w.GetModuleInformation(
        handle, ctypes.c_void_p(base), ctypes.byref(info), ctypes.sizeof(info)
    )
    if not ok:
        return None
    size = int(info.SizeOfImage)
    return size if size > 0 else None


def _image_extents(handle, pid):
    """Map every image allocation base onto the extent it spans."""
    extents = {}
    for base, size, state, mem_type, _protect, alloc_base in _walk(
        handle, pid
    ):
        if mem_type != w.MEM_IMAGE:
            continue
        if state == w.MEM_FREE:
            continue
        start = alloc_base or base
        end = base + size
        current = extents.get(start)
        if current is None or end > current:
            extents[start] = end
    return {start: end - start for start, end in extents.items()}


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image is listed once.  An image whose file name cannot be turned
    into an openable path is still listed, with ``path`` set to ``None``,
    because leaving it out would understate what the process has loaded.
    """
    handle = _open_process(pid)
    try:
        resolver = _PathResolver(handle)
        found = {}

        # The loader's own view: authoritative bases and real DOS paths.
        for base in _enumerate_module_handles(handle) or ():
            if not base:
                continue
            path = _module_file_name(handle, base)
            if path is not None:
                path = _dos_path(path, resolver.device_map)
            if path is None:
                path = resolver.resolve(base, is_image=True)
            found[base] = {
                "path": path,
                "base": base,
                "size": _module_size(handle, base),
            }

        # Anything mapped as an image that the loader list did not mention
        # (a different bitness, a manually mapped image, a racing load).
        for base, size in _image_extents(handle, pid).items():
            entry = found.get(base)
            if entry is None:
                found[base] = {
                    "path": resolver.resolve(base, is_image=True),
                    "base": base,
                    "size": size,
                }
            elif not entry["size"]:
                entry["size"] = size

        result = []
        seen_paths = set()
        for entry in sorted(found.values(), key=lambda item: item["base"]):
            if entry["path"] is not None:
                key = entry["path"].lower()
                if key in seen_paths:
                    continue
                seen_paths.add(key)
            if not entry["size"]:
                entry["size"] = 0
            result.append(entry)
        return result
    finally:
        w.CloseHandle(handle)

