    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

#: modifier bits that sit on top of a base protection value
_PROTECTION_MODIFIERS = w.PAGE_GUARD | w.PAGE_NOCACHE | w.PAGE_WRITECOMBINE

#: devices that name a network share rather than a local volume
_UNC_DEVICES = (
    "\\device\\mup",
    "\\device\\lanmanredirector",
    "\\device\\webdavredirector",
)

_max_application_address_cache = None


