    """Map a PAGE_* protection value onto its short textual name.

    Pure: a constant goes in, a name comes out, no process is consulted.  The
    guard and caching modifier bits are ignored, so ``PAGE_READWRITE |
    PAGE_GUARD`` still reads as ``rw``.
    """
    try:
        value = int(protect)
    except (TypeError, ValueError):
        return "?"
