    """Map a MEM_* region type onto its short textual name.

    Pure: a constant goes in, a name comes out, no process is consulted.
    """
    try:
        value = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(value, "private")


# ---------------------------------------------------------------------------
# process handles and failure classification
# ---------------------------------------------------------------------------

