"""Edge cases: exited processes, with and without a lingering handle."""

import subprocess
import sys
import time

import wvas

# A. killed and reaped -> the pid is gone for good
p = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(60)"])
pid = p.pid
p.kill()
p.wait()
time.sleep(0.2)
for fn in (wvas.regions, wvas.modules, wvas.file_backed_regions):
    try:
        print("reaped", fn.__name__, "returned", len(fn(pid)))
    except wvas.WVasError as e:
        print("reaped", fn.__name__, "->", e.kind)
    except Exception as e:
        print("reaped", fn.__name__, "LEAK", type(e).__name__, e)

# B. killed but subprocess still holds the handle -> pid still openable
q = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(60)"])
qid = q.pid
time.sleep(0.3)
q.kill()
time.sleep(0.3)
for fn in (wvas.regions, wvas.modules, wvas.file_backed_regions):
    try:
        print("zombie", fn.__name__, "returned", len(fn(qid)))
    except wvas.WVasError as e:
        print("zombie", fn.__name__, "->", e.kind)
    except Exception as e:
        print("zombie", fn.__name__, "LEAK", type(e).__name__, e)
q.wait()

# C. a pid that very likely never existed
for candidate in (0xFFFFFFFF, 0xFFFFFFFC, 123456788):
    try:
        print(candidate, "returned", len(wvas.regions(candidate)))
    except wvas.WVasError as e:
        print(candidate, "->", e.kind)
    except Exception as e:
        print(candidate, "LEAK", type(e).__name__, e)
